#pragma once

#include "lgfx_w5.h"

// Anti-aliased Rajdhani fonts, generated by tools/make_vlw_font.py
enum DashFont {
    FONT_S,     // 20 px: labels, artist
    FONT_M,     // 28 px: strip values, street, song title
    FONT_L,     // 46 px: time, RPM number, distance to turn
    FONT_XL,    // 118 px digits: speed
    FONT_HUGE,  // 150 px digits and N: gear
};

// Selects a font on a screen or sprite (reloads only when it changes).
void useFont(lgfx::LGFXBase& target, DashFont font);
